#pragma once
// Pure-C++ autoencoder inference + alarm debounce (no Arduino dependency).
// Weights/threshold come from model_weights.h / model_data.h (generated by train.py).
//
// Cost per inference: 96 multiply-accumulates + 4 expf. Flash: 472 B of weights.
// RAM: ~100 B of stack, no heap.

#include <stdint.h>
#include "preprocess.h"   // Features

struct InferenceResult {
    float input[4];            // normalized features
    float reconstructed[4];    // autoencoder output
    float reconstruction_mse;
    bool  is_anomaly;          // this single sample is above the threshold
};

class InferenceEngine {
public:
    InferenceResult run(const Features& f) const;
    static float threshold();
};

// Debounce: ALARM_ON_COUNT anomalous samples in a row raise the alarm,
// ALARM_OFF_COUNT normal samples in a row clear it. Mirrors pipeline.py:AlarmFilter.
class AlarmFilter {
public:
    bool update(bool is_anomaly);
    bool active() const { return active_; }

private:
    bool    active_ = false;
    uint8_t over_   = 0;
    uint8_t under_  = 0;
};
